changeSet.sql:
CREATE TABLE messages (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    chat_id           BIGINT NOT NULL,
    sender_profile_id BIGINT NOT NULL,
    text              TEXT   NOT NULL,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at        TIMESTAMPTZ,
    deleted_at        TIMESTAMPTZ,

    CONSTRAINT MESSAGES_CHAT_FK   FOREIGN KEY (chat_id)           REFERENCES chats(id)    ON DELETE CASCADE,
    CONSTRAINT MESSAGES_SENDER_FK FOREIGN KEY (sender_profile_id) REFERENCES profiles(id) ON DELETE CASCADE
);

CREATE INDEX idx_messages_chat   ON messages(chat_id, created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX idx_messages_sender ON messages(sender_profile_id)        WHERE deleted_at IS NULL;
